const client = new AtlasClient({
  baseUrl: process.env.ATLAS_BFF_URL!,
  token: process.env.ATLAS_BFF_TOKEN!,
});

// First poll: fresh body + ETag.
const first = await client.getPortfolioSummary();
// first.summary  → PortfolioSummary
// first.etag     → 'W/"abc123-deadbeef"'

// 30s later: second poll round-trips the ETag.
